import {scheduledPriority} from './batch-priority.js?v=0.21.1';
export const QUARTER_MILE=.25;
const TYPES={AVENUE:'AVE',STREET:'ST',ROAD:'RD',DRIVE:'DR',BOULEVARD:'BLVD',PLACE:'PL',COURT:'CT',LANE:'LN',CIRCLE:'CIR',TERRACE:'TER',PARKWAY:'PKWY',HIGHWAY:'HWY',NORTHWEST:'NW',SOUTHWEST:'SW',NORTHEAST:'NE',SOUTHEAST:'SE',NORTH:'N',SOUTH:'S',EAST:'E',WEST:'W'};
export function streetKey(value){return String(value||'').toUpperCase().replace(/\b(?:SEATTLE|WHITE CENTER|SHORELINE|BURIEN)\b.*$/,'').replace(/\b(?:WA|WASHINGTON)\b.*$/,'').replace(/\b(?:APT|APARTMENT|UNIT|STE|SUITE|BUILDING|BLDG|FLOOR)\b.*$|#.*$/,'').replace(/(\d+)(?:ST|ND|RD|TH)\b/g,'$1').replace(/[^A-Z0-9 /-]/g,' ').split(/\s+/).filter(Boolean).map(v=>TYPES[v]||v).join(' ').trim();}
export function distanceMiles(a,b){if(!a||!b)return null;const rad=x=>x*Math.PI/180,dlat=rad(b.lat-a.lat),dlon=rad(b.lon-a.lon),h=Math.sin(dlat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dlon/2)**2;return 3958.7613*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)));}
export function addressIndex(data){const map=new Map(),ambiguous=new Set();for(const [address,y,x] of data.rows){const key=data.normalized?address:streetKey(address),point={lat:y/data.coordinateScale,lon:x/data.coordinateScale};if(!map.has(key))map.set(key,point);else if(distanceMiles(map.get(key),point)>.10)ambiguous.add(key);}for(const key of ambiguous)map.delete(key);return map;}
let index=null,loading=null,loadError='';
export function loadLocations(){if(index)return Promise.resolve(index);if(!loading)loading=fetch('./data/seattle-addresses.json?v=2026-11-19',{cache:'force-cache'}).then(r=>{if(!r.ok)throw Error('Address locations are not downloaded yet.');return r.json();}).then(data=>index=addressIndex(data)).catch(e=>{loading=null;loadError=e.message;throw e;});return loading;}
export function locationFor(address,lookup=index){return lookup?.get(streetKey(address))||null;}
export function locationStatus(){return {ready:!!index,error:loadError};}
export function nearbyPairs(deliveries,lookup=index){const ds=deliveries.filter(d=>['pending','ready','active'].includes(d.status));const pairs=[];for(let i=0;i<ds.length;i++)for(let j=i+1;j<ds.length;j++){const miles=distanceMiles(locationFor(ds[i].address,lookup),locationFor(ds[j].address,lookup));if(miles!==null&&miles<=QUARTER_MILE)pairs.push({a:ds[i].id,b:ds[j].id,miles});}return pairs;}
const ticket=d=>/^\d+$/.test(String(d.ticket||''))?Number(d.ticket):Infinity;
const oldest=(a,b)=>ticket(a)-ticket(b)||Date.parse(a.enteredAt||'')-Date.parse(b.enteredAt||'')||String(a.id).localeCompare(String(b.id));
function closeTo(a,b,lookup){const miles=distanceMiles(locationFor(a.address,lookup),locationFor(b.address,lookup));return miles!==null&&miles<=QUARTER_MILE;}
function clusterFrom(seed,available,lookup){const group=[seed],seen=new Set([seed.id]);for(let i=0;i<group.length;i++)for(const d of available)if(!seen.has(d.id)&&closeTo(group[i],d,lookup)){seen.add(d.id);group.push(d);}return group;}
function clusterPath(group,seed,lookup){const nodes=[seed,...group.filter(d=>d.id!==seed.id).sort(oldest)],n=nodes.length;if(n<3)return nodes;const distance=(a,b)=>distanceMiles(locationFor(nodes[a].address,lookup),locationFor(nodes[b].address,lookup));if(n>10){const path=[seed],left=nodes.slice(1);while(left.length){left.sort((a,b)=>distanceMiles(locationFor(path.at(-1).address,lookup),locationFor(a.address,lookup))-distanceMiles(locationFor(path.at(-1).address,lookup),locationFor(b.address,lookup))||oldest(a,b));path.push(left.shift());}return path;}const states=new Array((1<<n)*n);states[n]={cost:0,path:[0]};for(let mask=1;mask<(1<<n);mask++)for(let last=0;last<n;last++){const current=states[mask*n+last];if(!current)continue;for(let next=1;next<n;next++)if(!(mask&(1<<next))){const key=(mask|(1<<next))*n+next,candidate={cost:current.cost+distance(last,next),path:[...current.path,next]},prior=states[key];if(!prior||candidate.cost<prior.cost-1e-10||Math.abs(candidate.cost-prior.cost)<1e-10&&candidate.path.join(',')<prior.path.join(','))states[key]=candidate;}}let best;for(let last=0;last<n;last++){const candidate=states[((1<<n)-1)*n+last];if(candidate&&(!best||candidate.cost<best.cost-1e-10||Math.abs(candidate.cost-best.cost)<1e-10&&candidate.path.join(',')<best.path.join(',')))best=candidate;}return best.path.map(i=>nodes[i]);}
export function suggestedOrder(deliveries,lookup=index){const scheduled=deliveries.filter(d=>scheduledPriority(d)).sort((a,b)=>Date.parse(a.scheduledAt)-Date.parse(b.scheduledAt)||oldest(a,b)),remaining=deliveries.filter(d=>!scheduledPriority(d)).sort(oldest),ordered=[...scheduled];while(remaining.length){const previous=ordered.at(-1),near=previous?remaining.filter(d=>closeTo(previous,d,lookup)):[];near.sort((a,b)=>distanceMiles(locationFor(previous.address,lookup),locationFor(a.address,lookup))-distanceMiles(locationFor(previous.address,lookup),locationFor(b.address,lookup))||oldest(a,b));const seed=near[0]||remaining[0],group=clusterFrom(seed,remaining,lookup),ids=new Set(group.map(d=>d.id));ordered.push(...clusterPath(group,seed,lookup));for(let i=remaining.length-1;i>=0;i--)if(ids.has(remaining[i].id))remaining.splice(i,1);}return {stops:ordered,unlocated:ordered.filter(d=>!locationFor(d.address,lookup)).map(d=>d.id)};}
